const response = pm.response.json();

// Validar status code
pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

// Validar que la respuesta sea un objeto
pm.test("La respuesta es un objeto", function () {
    pm.expect(response).to.be.an("object");
});

// Validar ID
pm.test("El producto tiene un ID numérico", function () {
    pm.expect(response).to.have.property("id");
    pm.expect(response.id).to.be.a("number");
    pm.expect(response.id).to.be.above(0);
});

// Validar title
pm.test("El producto tiene un título válido", function () {
    pm.expect(response).to.have.property("title");
    pm.expect(response.title).to.be.a("string");
    pm.expect(response.title.length).to.be.above(0);
});

// Validar price
pm.test("El precio es de tipo number", function () {
    pm.expect(response).to.have.property("price");
    pm.expect(response.price).to.be.a("number");
});

// Validar que el precio sea positivo
pm.test("El precio es mayor a cero", function () {
    pm.expect(response.price).to.be.above(0);
});

// Validar description
pm.test("La descripción es un string", function () {
    pm.expect(response).to.have.property("description");
    pm.expect(response.description).to.be.a("string");
});

// Validar category
pm.test("La categoría es un string", function () {
    pm.expect(response).to.have.property("category");
    pm.expect(response.category).to.be.a("string");
});

// Validar image
pm.test("La imagen es un string", function () {
    pm.expect(response).to.have.property("image");
    pm.expect(response.image).to.be.a("string");
});

// Validar estructura rating
pm.test("El objeto rating tiene rate y count", function () {
    pm.expect(response).to.have.property("rating");
    pm.expect(response.rating).to.be.an("object");
    pm.expect(response.rating).to.have.property("rate");
    pm.expect(response.rating).to.have.property("count");
});

// Validar tipos dentro de rating
pm.test("Rate y count son números", function () {
    pm.expect(response.rating.rate).to.be.a("number");
    pm.expect(response.rating.count).to.be.a("number");
});

